this.visabilityController = function  (id) {
	var temp;
	switch (id) {
		case "1":
			temp = this.context.binding.get("value").get("contractcashCollateralsOption").get("listAllItems");
			if (temp.length > 0) {
				this.ui.get("contract_cash_collaterals").setVisible(true, true);
			} else {
				this.ui.get("contract_cash_collaterals").setVisible(false, true);
			}
			break;
		case "2":
			temp = this.context.binding.get("value").get("advicesOption").get("listAllItems");
			if (temp.length > 0) {
				this.ui.get("contract_advices").setVisible(true, true);
			} else {
				this.ui.get("contract_advices").setVisible(false, true);
			}
			break;
		case "3":
			temp = this.context.binding.get("value").get("contractLimitsTrackingOption").get("listAllItems");
			if (temp.length > 0) {
				this.ui.get("contract_limits_tracking").setVisible(true, true);
			} else {
				this.ui.get("contract_limits_tracking").setVisible(false, true);
			}
			break;
		case "4":
			temp = this.context.binding.get("value").get("contractInterestDetailsOption").get("listAllItems");
			if (temp.length > 0) {
				this.ui.get("contract_Interest_Details").setVisible(true, true);
			} else {
				this.ui.get("contract_Interest_Details").setVisible(false, true);
			}
			break;
		case "5":
			temp = this.context.binding.get("value").get("contractTransactionDetailsOption").get("listAllItems");
			if (temp.length > 0) {
				this.ui.get("contract_transaction_details").setVisible(true, true);
			} else {
				this.ui.get("contract_transaction_details").setVisible(false, true);
			}
			break;
		default:
			break;
	}
}

this.handleError = function(errorCode, errorMessage) {
	console.log('Error occurred: ' + errorCode + ' - ' + errorMessage);
	this.context.binding.get('value').get('errorMessage').setValue(errorMessage);
	this.context.binding.get('value').get('errorType').setValue(errorCode);
	this.ui.get('errorPanel').setVisible(true, true);
};

this.clearError = function() {
	this.context.binding.get('value').get('errorMessage').setValue('');
	this.ui.get('errorPanel').setVisible(false, true);
};

details.loadJsFunction:
// Initialize basic details view
this.ui.get('customerPanel').setVisible(true, true);
this.ui.get('contractPanel').setVisible(true, true);

// Load customer information
var customerData = this.context.binding.get('value').get('customer');
if (customerData) {
    this.ui.get('customerName').setText(customerData.get('name'));
    this.ui.get('customerCIF').setText(customerData.get('cif'));
}

// Load contract information
var contractData = this.context.binding.get('value').get('contract');
if (contractData) {
    this.ui.get('contractNumber').setText(contractData.get('number'));
    this.ui.get('contractAmount').setText(contractData.get('amount'));
}

inlineScripts.scriptBlock:
this.validateBasicDetails = function() {
    var isValid = true;
    var errors = [];

    // Validate customer information
    var customer = this.context.binding.get('value').get('customer');
    if (!customer || !customer.get('name')) {
        errors.push('Customer name is required');
        isValid = false;
    }

    if (!customer || !customer.get('cif')) {
        errors.push('Customer CIF is required');
        isValid = false;
    }

    // Validate contract information
    var contract = this.context.binding.get('value').get('contract');
    if (!contract || !contract.get('number')) {
        errors.push('Contract number is required');
        isValid = false;
    }

    if (!contract || contract.get('amount') <= 0) {
        errors.push('Contract amount must be greater than zero');
        isValid = false;
    }

    // Display validation results
    if (!isValid) {
        this.ui.get('errorMessage').setText(errors.join(', '));
        this.ui.get('errorPanel').setVisible(true, true);
    } else {
        this.ui.get('errorPanel').setVisible(false, true);
    }

    return isValid;
};

this.formatCurrency = function(amount) {
    return new Intl.NumberFormat('en-US', {
        style: 'currency',
        currency: 'USD'
    }).format(amount);
};

this.formatDisplayData = function() {
    // Format customer display
    var customerName = this.context.binding.get('value').get('customer').get('name');
    var customerCIF = this.context.binding.get('value').get('customer').get('cif');
    this.ui.get('customerDisplay').setText(customerName + ' (' + customerCIF + ')');

    // Format contract display
    var contractNumber = this.context.binding.get('value').get('contract').get('number');
    var contractAmount = this.context.binding.get('value').get('contract').get('amount');
    this.ui.get('contractDisplay').setText('Contract #' + contractNumber + ' - ' + this.formatCurrency(contractAmount));
};
